# Let me verify by tracing through the BFS levels explicitly
def bfs_with_levels(graph, start):
    distance = {start: 0}
    queue = deque([start])
    levels = {0: [start]}

    while queue:
        node = queue.popleft()
        current_dist = distance[node]

        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = current_dist + 1
                queue.append(neighbor)
                if current_dist + 1 not in levels:
                    levels[current_dist + 1] = []
                levels[current_dist + 1].append(neighbor)

    return levels, distance

